const ticket = $json;

const errors = [];

if (ticket.ticket_id === undefined || ticket.ticket_id === null) {
  errors.push("Missing ticket_id");
}

if (typeof ticket.message !== "string" || !ticket.message.trim()) {
  errors.push("Missing or invalid message");
}

if (typeof ticket.product !== "string" || !ticket.product.trim()) {
  errors.push("Missing or invalid product");
}

let email = typeof ticket.customer_email === "string"
  ? ticket.customer_email.trim().toLowerCase()
  : "";

email = email.replace(
  /^([^@]+)\+[^@]*(@gmail\.com)$/i,
  "$1$2"
);

return {
  json: {
    ...ticket,
    customer_email: email,
    validation_status: errors.length ? "invalid" : "valid",
    validation_errors: errors
  }
};

const ticket = $json;
const message = ticket.message.toLowerCase();

let intent = "other";

if (
  message.includes("refund") ||
  message.includes("money back")
) {
  intent = "refund";
} else if (
  message.includes("cancel") &&
  (
    message.includes("charged") ||
    message.includes("charge") ||
    message.includes("billing")
  )
) {
  intent = "cancellation_with_billing_clarification";
} else if (message.includes("cancel")) {
  intent = "cancellation";
} else if (
  message.includes("freez") ||
  message.includes("login") ||
  message.includes("technical") ||
  message.includes("error")
) {
  intent = "technical_issue";
}

return {
  ...ticket,
  intent,
  confidence: null,
  classifier_mode: "mock"
};

const d = $json;

const subscriptions = Array.isArray(d.subscriptions)
  ? d.subscriptions
  : [];

const matchingSubscriptions = subscriptions.filter(
  sub =>
    String(sub.product ?? "").trim().toLowerCase() ===
    String(d.product ?? "").trim().toLowerCase()
);

const activeSubscriptions = matchingSubscriptions.filter(
  sub => String(sub.status ?? "").toLowerCase() === "active"
);

const matching_subscription_count = matchingSubscriptions.length;

let action_status;
let reason;
let billing_provider = null;
let subscription_id = null;

if (activeSubscriptions.length === 1) {
  action_status = "simulated_success";
  reason = null;
  subscription_id = activeSubscriptions[0].id ?? null;
  billing_provider = activeSubscriptions[0].billing_provider ?? null;
} else if (activeSubscriptions.length === 0) {
  action_status = "not_executed";
  reason = "No matching active subscription found";
} else {
  action_status = "requires_review";
  reason = "Multiple matching active subscriptions found";
}

return {
  ...d,
  intent: d.intent ?? "cancellation",
  matching_subscription_count,
  action_type: "cancellation",
  action_status,
  details: {
    reason,
    subscription_id,
    billing_provider,
    active_subscription_count: activeSubscriptions.length
  },
  execution_status: "Success",
  error_message: null,
  response_context: null
};

const d = $json;
const subs = Array.isArray(d.subscriptions) ? d.subscriptions : [];

const matching = subs.filter(s => s.product === d.product);
const matching_subscription_count = matching.length;
const eligible = matching_subscription_count >= 1;

return {
  json: {
    ...d,

    matching_subscription_count,
    action_type: 'refund',

    // Запит лише симулюється, реального повернення коштів немає
    action_status: eligible
      ? 'requires_review'
      : 'not_executed',

    execution_status: 'Success',

    error_message: eligible
      ? null
      : 'No subscription found for this product',

    response_context: eligible
      ? 'Refund request requires manual review. Do not claim that a refund has been approved or processed.'
      : 'No matching subscription found. Explain that the refund request could not proceed.',

    details: {
      reason: eligible
        ? 'Refund requires manual review'
        : 'No subscription found for this product',
      matching_subscription_count,
      refund_eligible: eligible
    }
  }
};

const d = $json;

return {
  json: {
    ...d,

    action_type: "technical_support",
    action_status: "queued",

    details: d.details ?? {
      reason: "Technical issue requires manual review"
    },

    execution_status: "Success",
    error_message: null,

    response_context:
      d.response_context ??
      "Route the technical issue to the technical support team for manual review."
  }
};

const d = $json;

return {
  json: {
    ...d,
    action_type: "manual_review",
    action_status: "requires_review",
    details: {
      ...(d.details ?? {}),
      reason:
        d.details?.reason ??
        "General support request requires manual review"
    },
    matching_subscription_count:
      d.matching_subscription_count ?? 0,
    execution_status: "Success",
    error_message: d.error_message ?? null,
    response_context:
      d.response_context ??
      "Route the request to the general support queue for manual review. Do not claim that the issue has already been resolved."
  }
};

const d = $json;

const subscriptions = Array.isArray(d.subscriptions)
  ? d.subscriptions
  : [];

const matchingSubscriptions = subscriptions.filter(
  sub =>
    String(sub.product ?? "").trim().toLowerCase() ===
    String(d.product ?? "").trim().toLowerCase()
);

const activeSubscriptions = matchingSubscriptions.filter(
  sub => String(sub.status ?? "").toLowerCase() === "active"
);

const matching_subscription_count = matchingSubscriptions.length;

let action_status;
let reason;
let billing_provider = null;
let subscription_id = null;

if (activeSubscriptions.length === 1) {
  action_status = "simulated_success";
  reason = null;
  subscription_id = activeSubscriptions[0].id ?? null;
  billing_provider = activeSubscriptions[0].billing_provider ?? null;
} else if (activeSubscriptions.length === 0) {
  action_status = "not_executed";
  reason = "No matching active subscription found";
} else {
  action_status = "requires_review";
  reason = "Multiple matching active subscriptions found";
}

return {
  ...d,
  intent: d.intent ?? "cancellation_with_billing_clarification",
  matching_subscription_count,
  action_type: "cancellation_with_billing_clarification",
  action_status,
  details: {
    reason,
    subscription_id,
    billing_provider,
    active_subscription_count: activeSubscriptions.length
  },
  execution_status: "Success",
  error_message: null,
  response_context: billing_provider
    ? `The customer asked about a charge and cancellation. Billing provider: ${billing_provider}.`
    : "The customer asked about a charge and cancellation. Billing provider could not be determined."
};

const ticket = $json;

return {
  ...ticket,
  intent: "invalid",
  action_type: "none",
  action_status: "not_executed",
  execution_status: "Failed",
  error_message: (ticket.validation_errors || []).join("; ") || "Ticket failed validation",
  processed: true
};

