const aiItems = $input.all();
const originalItems = $('Merge3').all();

return aiItems.map((item, index) => {
  const original = originalItems[index]?.json ?? {};
  const ai = item.json;

  const rawText =
    ai.content?.parts?.[0]?.text ??
    ai.response_text ??
    '';

  let responseText = String(rawText).trim();

  try {
    const parsed = JSON.parse(responseText);
    responseText = parsed.response ?? responseText;
  } catch (e) {

  }

  return {
    json: {
      ...original,
      response_text: responseText,
      response_valid: responseText.length > 0,
      response_status: responseText.length > 0
        ? 'success'
        : 'error'
    }
  };
});

const items = $input.all();

return items.map(item => {
  const d = item.json;

  return {
    json: {
      timestamp: new Date().toISOString(),

      ticket_id: d.ticket_id ?? null,
      detected_intent: d.intent ?? null,
      matching_subscription_count:
        d.matching_subscription_count ?? null,

      action_type: d.action_type ?? null,
      action_status: d.action_status ?? null,
      execution_status: d.execution_status ?? null,
      error_message: d.error_message ?? null,

      customer_email: d.customer_email ?? null,
      product: d.product ?? null,
      subject: d.subject ?? null,
      message: d.message ?? null,

      response_text: d.response_text ?? null,
      response_valid: d.response_valid ?? false,
      response_status: d.response_status ?? "unknown"
    }
  };
});
